using System.Text;
using System.Text.Json;
using Curia.Canon;
using Curia.Canon.Canonical;
using Curia.Canon.Envelope;
using Curia.Canon.Jws;
using static GenerateEnvelopeFixtures.JsonBuilders;
using JsonValue = Curia.Canon.Json.JsonValue;

namespace GenerateEnvelopeFixtures;

/// <summary>
/// PR 2's cases (keys that end, Task 2.0), regenerated by PR H (errata G67, R6.62) under the declaration key: whole small logs that carry the operator's
/// compromise declaration, and the <c>acta/key-compromised-entry</c> vector. Run by <c>--compromise</c>, and first run in Task 2.3: a declaration is signed
/// ES256 by a fixed P-256 declaration key, ES256 signing is randomized, so the first run pins each declaration's signature bytes and
/// every later run re-verifies the pinned signature and keeps it. The generator never re-signs a declaration, and refuses
/// a case whose pinned statement changed rather than re-sign it (spec 4.6).
///
/// <para>Every declaration's statement <c>typ</c> is <c>curia.key-compromise/2</c>, its header <c>typ</c> is <c>curia-key-compromise+jws</c> and its header
/// <c>kid</c> is the declaration key's, a key published by a <c>log.declaration-key</c> entry and served in <c>declaration_keys</c> (KF1, KF2, R6.62), except in the
/// cases that exist to break exactly that. Each case holds one defect (KF3, KF4).</para>
/// </summary>
internal static partial class LifecycleCases
{
    private const string CompromiseHeaderTyp = "curia-key-compromise+jws";
    private const string CompromiseTyp = "curia.key-compromise/2";
    private const string OperatorRole = "operator";
    private const string LogKeyValidFrom = "2026-09-01T00:00:00Z";

    private sealed record Decl(P256LogKey Signer, string[] Kids, long FromIndex, long Prev)
    {
        public string Reason { get; init; } = "owner-reported";
        public string StatementTyp { get; init; } = CompromiseTyp;
        public string HeaderTyp { get; init; } = CompromiseHeaderTyp;
    }

    public static int RunCompromise(string repoRoot)
    {
        var status = Lifecycle.RunCompromiseVector(repoRoot);
        if (status != 0)
            return status;

        var root = Path.Combine(repoRoot, "conformance", "lifecycle");
        Directory.CreateDirectory(root);

        using var firstDoc = JsonDocument.Parse(File.ReadAllBytes(
            Path.Combine(repoRoot, "conformance", "envelope", "ed25519-minimal", "private-keys.json")));
        var firstJwk = firstDoc.RootElement.GetProperty("keys")[0];
        var k1 = Ed("conformance-ed25519-minimal", Jwk.Base64UrlDecode(firstJwk.GetProperty("d").GetString()!));
        var k2 = Ed("conformance-ed25519-second", Enumerable.Repeat((byte)0x02, 32).ToArray());
        var k3 = Ed("conformance-ed25519-third", Enumerable.Repeat((byte)0x03, 32).ToArray());
        var stranger = Ed("conformance-ed25519-stranger", Enumerable.Repeat((byte)0x09, 32).ToArray());

        var cases = new List<Case>
        {
            CompromisedBeforePost(root, k1),
            CompromisedAfterInterveningRotation(root, k1, k2, "compromised-after-intervening-rotation", reorderKids: false, omitCascade: false),
            DeclarationSignedAsHead(root, k1),
            CompromisedAfterInterveningRotation(root, k1, k2, "compromise-kids-omits-cascade", reorderKids: false, omitCascade: true),
            FromIndexAfterDeclaration(root, k1),
            FromIndexAtDeclaration(root, k1),
            KidOfOtherIdentity(root, k1, stranger),
            UnknownReason(root, k1),
            DeclarationKidNotValidAtPosition(root, k1),
            DeclarationKidPositionUnknown(root, k1),
            V1Statement(root, k1),
            SignedByLogKey(root, k1),
            DeclarationKeyIsLogKey(root, k1),
            TwoDeclarationKeys(root, k1, underFirst: false),
            TwoDeclarationKeys(root, k1, underFirst: true),
            DeclarationKeySetAbsent(root, k1),
            DeclarationKeysEmpty(root, k1),
            FromIndexBeforeBinding(root, k1),
            CompromisedAfterInterveningRotation(root, k1, k2, "compromise-kids-reordered", reorderKids: true, omitCascade: false),
            PostUnderCascadedKey(root, k1, k2),
            KidsSiblingsReordered(root, k1, k2, k3),
            SiblingDeclaredAlone(root, k1, k2, k3),
        };

        var logSeed = Enumerable.Repeat((byte)0x05, 32).ToArray();
        var logPublic = PublicOf(logSeed);
        foreach (var c in cases)
            Write(root, c, logSeed, logPublic);

        Console.WriteLine($"compromise cases written under conformance/lifecycle/ ({cases.Count} written)");
        return 0;
    }

    // ---- cases ---------------------------------------------------------------------------------

    /// <summary>0 enrolled, 1 binding, 2 the post, 3 the declaration key's publication, 4 the declaration (kids [k1], from_index 1, prev 1).</summary>
    private static (Log Log, int Post, int LogKeyIndex, Decl Decl) PostThenDeclaration(Key k1, string nonce, Func<Decl, Decl>? adjust = null)
    {
        var log = EnrolledAndBound(k1);
        var post = AddPost(log, k1, nonce);
        var logKeyIndex = PublishDeclarationKey(log, ConformanceLogKeys.Declaration);
        var decl = new Decl(ConformanceLogKeys.Declaration, [k1.Kid], FromIndex: 1, Prev: 1);
        return (log, post, logKeyIndex, adjust is null ? decl : adjust(decl));
    }

    private static Case CompromisedBeforePost(string root, Key k1)
    {
        var (log, post, logKeyIndex, decl) = PostThenDeclaration(k1, "40");
        AddDeclaration(log, decl, root, "compromised-before-post");
        return new Case("compromised-before-post", "R6.57",
            "The post at 2 is signed by the enrolled key; the operator's declaration at 4 names that key from log index 1, its binding, so the key was declared compromised from before the post. The signature holds and the content is disputed.",
            log, post, [0, 1, 4], "disputed", "disputed")
        { DeclarationKeys = [new ExtraLogKey(ConformanceLogKeys.Declaration, LogKeyValidFrom, logKeyIndex)] };
    }

    /// <summary>
    /// 0 enrolled, 1 binding k1, 2 the post, 3 the rotation k1 to k2 (so k2 is in the cascade), 4 the declaration key's publication, 5 the declaration.
    /// The disputed variant and the omits-cascade variant use from_index 2, at or below the post (kids[0] is k1, bound at 1). The
    /// reordered variant puts k2 first, bound at 3, so it uses from_index 3 (binding 3 &lt;= 3 &lt; 5; the cascade from 3 is still
    /// [k1, k2], R6.57's membership being at or after from_index): the one defect of both failed variants is in <c>kids</c>.
    /// </summary>
    private static Case CompromisedAfterInterveningRotation(
        string root, Key k1, Key k2, string name, bool reorderKids, bool omitCascade)
    {
        var log = EnrolledAndBound(k1);
        var post = AddPost(log, k1, "41");
        AddRotation(log, new Rot(k1, k2, Prev: 1));
        var logKeyIndex = PublishDeclarationKey(log, ConformanceLogKeys.Declaration);
        var kids = reorderKids ? new[] { k2.Kid, k1.Kid } : omitCascade ? [k1.Kid] : new[] { k1.Kid, k2.Kid };
        var fromIndex = reorderKids ? 3 : 2;
        AddDeclaration(log, new Decl(ConformanceLogKeys.Declaration, kids, FromIndex: fromIndex, Prev: 3), root, name);
        var (verdict, predicate, note) = name switch
        {
            "compromise-kids-omits-cascade" => ("failed", "declaration-mismatch",
                "The declaration names the compromised key alone, though the rotation at 3 was authorized by it after from_index: the recomputed cascade is [k1, k2] and kids omits k2 (KF3)."),
            "compromise-kids-reordered" => ("failed", "declaration-mismatch",
                "The correct cascade with its first two kids swapped: kids is [k2, k1] where the compromised key, the post's k1, comes first. from_index is 3, so binding(kids[0]) = binding(k2) = 3 holds the bound, 3 is below the declaration at 5, and the cascade from 3 is still [k1, k2]: the only defect is the order (KF3)."),
            _ => ("disputed", "disputed",
                "The post at 2, a rotation at 3 authorized by the post's key, and the declaration at 5 with from_index 2 at or below the post: the rotation lies between the post and the declaration, and the post is still disputed. The cascade holds two kids."),
        };
        return new Case(name, "R6.57", note, log, post, [0, 1, 3, 5], verdict, predicate)
        { DeclarationKeys = [new ExtraLogKey(ConformanceLogKeys.Declaration, LogKeyValidFrom, logKeyIndex)] };
    }

    /// <summary>
    /// 0 enrolled, 1 binding k1, 2 the rotation k1 to k2, 3 the post, signed by k2 (the cascaded key), 4 the declaration key's publication, 5 the
    /// declaration naming [k1, k2] from index 1. The cascade is rooted at the declaration's earliest-bound kid (k1, bound at 1), not
    /// at the post's key: rooted at k2 the cascade would be [k2] and the correct declaration would fail <c>declaration-mismatch</c>.
    /// The post at 3 lies in [1, 5) and its key is in kids, so it is disputed. The key set names this declaration for k2 as well as
    /// for k1 (<c>curia_compromised_log_index</c>), which is what lets a reader fetch it for a post under k2.
    /// </summary>
    private static Case PostUnderCascadedKey(string root, Key k1, Key k2)
    {
        var log = EnrolledAndBound(k1);
        AddRotation(log, new Rot(k1, k2, Prev: 1));
        var post = AddPost(log, k2, "51");
        var logKeyIndex = PublishDeclarationKey(log, ConformanceLogKeys.Declaration);
        AddDeclaration(log, new Decl(ConformanceLogKeys.Declaration, [k1.Kid, k2.Kid], FromIndex: 1, Prev: 2), root, "compromise-post-under-cascaded-key");
        return new Case("compromise-post-under-cascaded-key", "R6.57",
            "The declaration at 5 names [k1, k2], the cascade rooted at the compromised key k1 (bound at 1) from_index 1: k2 was rotated in by k1 at 2. The post at 3 is signed by k2, a key in kids, and lies in [1, 5): it is disputed. A reader that rooted the cascade at the post's key would recompute [k2] and refuse the correct declaration (KF3).",
            log, post, [0, 1, 2, 5], "disputed", "disputed")
        { DeclarationKeys = [new ExtraLogKey(ConformanceLogKeys.Declaration, LogKeyValidFrom, logKeyIndex)] };
    }

    /// <summary>
    /// 0 enrolled, 1 binding k1, 2 the post, 3 the rotation k1 to k2, 4 the rotation k1 to k3 (two rotations by k1, so two siblings),
    /// 5 the declaration key's publication, 6 the declaration naming [k1, k3, k2] from index 2. kids[0] is the root and every other check holds
    /// (binding(k1) 1 &lt;= 2 &lt; 6); the cascade in the log order of the bindings is [k1, k2, k3], so the only defect is the order
    /// of the siblings. A reader that compares kids as a set accepts it (KF3).
    /// </summary>
    private static Case KidsSiblingsReordered(string root, Key k1, Key k2, Key k3)
    {
        var log = EnrolledAndBound(k1);
        var post = AddPost(log, k1, "52");
        AddRotation(log, new Rot(k1, k2, Prev: 1));
        AddRotation(log, new Rot(k1, k3, Prev: 3));
        var logKeyIndex = PublishDeclarationKey(log, ConformanceLogKeys.Declaration);
        AddDeclaration(log, new Decl(ConformanceLogKeys.Declaration, [k1.Kid, k3.Kid, k2.Kid], FromIndex: 2, Prev: 4), root, "compromise-kids-siblings-reordered");
        return new Case("compromise-kids-siblings-reordered", "R6.57",
            "k1 rotated in k2 at 3 and k3 at 4, so the cascade from index 2 is [k1, k2, k3] in the log order of the bindings. The declaration at 6 names [k1, k3, k2]: kids[0] is the root, from_index 2 holds the bound, and the only defect is the order of the two siblings (KF3).",
            log, post, [0, 1, 3, 4, 6], "failed", "declaration-mismatch")
        { DeclarationKeys = [new ExtraLogKey(ConformanceLogKeys.Declaration, LogKeyValidFrom, logKeyIndex)] };
    }

    /// <summary>
    /// 0 enrolled, 1 binding k1, 2 the rotation k1 to k2, 3 the rotation k1 to k3 (two rotations by k1, so two siblings), 4 the post,
    /// signed by k2, 5 the declaration key's publication, 6 the declaration naming [k2] alone from index 2. k2 is the compromised key and it bound nothing:
    /// k3 was bound by k1, not by k2, so it is not in k2's cascade (R6.57: a key a compromised key bound by rotation), and the
    /// cascade rooted at k2 is [k2]. A reader that cascades every rotation at or after from_index, whoever authorized it, recomputes
    /// [k2, k3] and refuses the correct declaration. The post at 4 lies in [2, 6) under a key in kids, so it is disputed.
    /// </summary>
    private static Case SiblingDeclaredAlone(string root, Key k1, Key k2, Key k3)
    {
        var log = EnrolledAndBound(k1);
        AddRotation(log, new Rot(k1, k2, Prev: 1));
        AddRotation(log, new Rot(k1, k3, Prev: 2));
        var post = AddPost(log, k2, "53");
        var logKeyIndex = PublishDeclarationKey(log, ConformanceLogKeys.Declaration);
        AddDeclaration(log, new Decl(ConformanceLogKeys.Declaration, [k2.Kid], FromIndex: 2, Prev: 3), root, "compromise-sibling-declared-alone");
        return new Case("compromise-sibling-declared-alone", "R6.57",
            "k1 rotated in k2 at 2 and k3 at 3. The declaration at 6 names k2 alone from index 2: k3 was bound by k1, not by the compromised key k2, so the cascade rooted at k2 is [k2] and the declaration holds. The post at 4 is signed by k2 and lies in [2, 6): it is disputed. A reader that drops the authorizer clause and cascades every rotation at or after from_index recomputes [k2, k3] and refuses it (KF3).",
            log, post, [0, 1, 2, 3, 6], "disputed", "disputed")
        { DeclarationKeys = [new ExtraLogKey(ConformanceLogKeys.Declaration, LogKeyValidFrom, logKeyIndex)] };
    }

    private static Case DeclarationSignedAsHead(string root, Key k1)
    {
        var (log, post, logKeyIndex, decl) = PostThenDeclaration(k1, "42", d => d with { HeaderTyp = DetachedJws.HeadTyp });
        AddDeclaration(log, decl, root, "declaration-signed-as-head");
        return new Case("declaration-signed-as-head", "R6.57",
            "A valid declaration-key signature over the declaration whose header typ is curia-head+jws, a head's, not curia-key-compromise+jws (KF1).",
            log, post, [0, 1, 4], "failed", "lifecycle-typ-mismatch")
        { DeclarationKeys = [new ExtraLogKey(ConformanceLogKeys.Declaration, LogKeyValidFrom, logKeyIndex)] };
    }

    private static Case FromIndexAfterDeclaration(string root, Key k1)
    {
        var (log, post, logKeyIndex, decl) = PostThenDeclaration(k1, "43", d => d with { FromIndex = 5 });
        AddDeclaration(log, decl, root, "compromise-from-index-after-declaration");
        return new Case("compromise-from-index-after-declaration", "R6.57",
            "from_index is 5 and the declaration is at 4: from_index is not below the declaration's index (KF3).",
            log, post, [0, 1, 4], "failed", "declaration-mismatch")
        { DeclarationKeys = [new ExtraLogKey(ConformanceLogKeys.Declaration, LogKeyValidFrom, logKeyIndex)] };
    }

    private static Case FromIndexAtDeclaration(string root, Key k1)
    {
        var (log, post, logKeyIndex, decl) = PostThenDeclaration(k1, "50", d => d with { FromIndex = 4 });
        AddDeclaration(log, decl, root, "compromise-from-index-at-declaration");
        return new Case("compromise-from-index-at-declaration", "R6.57",
            "from_index is 4 and the declaration is at 4: from_index is not strictly below the declaration's index (KF3).",
            log, post, [0, 1, 4], "failed", "declaration-mismatch")
        { DeclarationKeys = [new ExtraLogKey(ConformanceLogKeys.Declaration, LogKeyValidFrom, logKeyIndex)] };
    }

    /// <summary>
    /// 0 enrolled, 1 binding k1, 2 the stranger's binding (another identity's stream), 3 the post, 4 the declaration key's publication, 5 the declaration
    /// naming the stranger's key, from_index 2. Entry 2 stays in the log but is not in the agent's stream, so it is not supplied
    /// (supplied [0, 1, 5]): a reader is only ever served the agent's own stream, and a foreign entry in the supplied set is
    /// foreign-identity-entry's case, not this one. The stranger's key has no binding in the stream, so check (1) fires and nothing
    /// earlier does. The recomputed cascade is [k1], so kids cannot equal it either; that is unavoidable, which is why the
    /// predicate is the distinct <c>kid-not-bound-to-agent</c> and a reader checks it before the cascade.
    /// </summary>
    private static Case KidOfOtherIdentity(string root, Key k1, Key stranger)
    {
        var log = EnrolledAndBound(k1);
        log.Add("agent.key-bound", OtherAgent, OtherAgent, Obj(
            ("agent_id", Str(OtherAgent)), ("jwk", stranger.Jwk), ("kid", Str(stranger.Kid))));
        var post = AddPost(log, k1, "44");
        var logKeyIndex = PublishDeclarationKey(log, ConformanceLogKeys.Declaration);
        AddDeclaration(log, new Decl(ConformanceLogKeys.Declaration, [stranger.Kid], FromIndex: 2, Prev: 1), root, "compromise-kid-of-other-identity");
        return new Case("compromise-kid-of-other-identity", "R6.57",
            "The declaration for this identity names a key that another identity's binding at 2 holds. The binding is in another identity's stream and is not supplied, so kids[0] has no binding to agent_id in the stream the reader holds (KF3, check 1). The log keeps that binding at 2, which is why from_index is 2.",
            log, post, [0, 1, 5], "failed", "kid-not-bound-to-agent")
        { DeclarationKeys = [new ExtraLogKey(ConformanceLogKeys.Declaration, LogKeyValidFrom, logKeyIndex)] };
    }

    private static Case UnknownReason(string root, Key k1)
    {
        var (log, post, logKeyIndex, decl) = PostThenDeclaration(k1, "45", d => d with { Reason = "key-lost" });
        AddDeclaration(log, decl, root, "compromise-unknown-reason");
        return new Case("compromise-unknown-reason", "R6.57",
            "The declaration's reason is key-lost, outside the closed set: a reader that does not know it cannot check the declaration (KF4).",
            log, post, [0, 1, 4], "could-not-check", "unknown-reason")
        { DeclarationKeys = [new ExtraLogKey(ConformanceLogKeys.Declaration, LogKeyValidFrom, logKeyIndex)] };
    }

    /// <summary>0 enrolled, 1 binding, 2 the post, 3 the declaration, 4 the declaration key that signed it: published after.</summary>
    private static Case DeclarationKidNotValidAtPosition(string root, Key k1)
    {
        var log = EnrolledAndBound(k1);
        var post = AddPost(log, k1, "46");
        AddDeclaration(log, new Decl(ConformanceLogKeys.Declaration, [k1.Kid], FromIndex: 1, Prev: 1), root, "compromise-declaration-kid-not-valid-at-position");
        var logKeyIndex = PublishDeclarationKey(log, ConformanceLogKeys.Declaration);
        return new Case("compromise-declaration-kid-not-valid-at-position", "R6.57",
            "The declaration at 3 verifies under a declaration key whose log.declaration-key entry is at 4, after it: the key was not published before the declaration it signs (KF2, R6.62(f)). This case is generated by the tool directly; the use case refuses it.",
            log, post, [0, 1, 3], "failed", "declaration-key-unpublished")
        { DeclarationKeys = [new ExtraLogKey(ConformanceLogKeys.Declaration, LogKeyValidFrom, logKeyIndex)] };
    }

    private static Case DeclarationKidPositionUnknown(string root, Key k1)
    {
        var (log, post, _, decl) = PostThenDeclaration(k1, "47");
        AddDeclaration(log, decl, root, "compromise-declaration-kid-position-unknown");
        return new Case("compromise-declaration-kid-position-unknown", "R6.57",
            "The key set lists the declaring declaration key with no log_index: a reader cannot say it was published before the declaration (KF2, R6.62(c), KF4's rule).",
            log, post, [0, 1, 4], "could-not-check", "declaration-key-position-unknown")
        { DeclarationKeys = [new ExtraLogKey(ConformanceLogKeys.Declaration, LogKeyValidFrom, LogIndex: null)] };
    }

    /// <summary>
    /// A <c>/1</c> statement under the test log key (errata G67): the statement version this reader does not know is read before the signer, so the declaration is
    /// could not be checked whoever signed it, and never disputes. 0 enrolled, 1 binding, 2 the post, 3 the declaration key's publication, 4 the declaration.
    /// </summary>
    private static Case V1Statement(string root, Key k1)
    {
        var (log, post, declarationKeyIndex, decl) = PostThenDeclaration(
            k1, "54", d => d with { Signer = ConformanceLogKeys.Log, StatementTyp = "curia.key-compromise/1" });
        AddDeclaration(log, decl, root, "compromise-v1-statement");
        return new Case("compromise-v1-statement", "R6.62",
            "A curia.key-compromise/1 statement, signed by the test log key under header typ curia-key-compromise+jws: /1 is withdrawn, so its statement typ is one this reader does not know (KF4), read before the signer, and the declaration is could not be checked whoever signed it. It never disputes.",
            log, post, [0, 1, 4], "could-not-check", "unknown-lifecycle-kind")
        { DeclarationKeys = [new ExtraLogKey(ConformanceLogKeys.Declaration, LogKeyValidFrom, declarationKeyIndex)] };
    }

    /// <summary>
    /// A <c>/2</c> declaration whose header kid is a log key: 0 enrolled, 1 binding, 2 the post, 3 the log key's publication (<c>log.key</c>), 4 the declaration key's
    /// publication, 5 the declaration, signed by the log key. The log key is no declaration key the log published (R6.62(b)).
    /// </summary>
    private static Case SignedByLogKey(string root, Key k1)
    {
        var log = EnrolledAndBound(k1);
        var post = AddPost(log, k1, "55");
        var logKeyIndex = PublishLogKey(log, ConformanceLogKeys.Log);
        var declarationKeyIndex = PublishDeclarationKey(log, ConformanceLogKeys.Declaration);
        AddDeclaration(log, new Decl(ConformanceLogKeys.Log, [k1.Kid], FromIndex: 1, Prev: 1), root, "compromise-signed-by-log-key");
        return new Case("compromise-signed-by-log-key", "R6.62",
            "A /2 declaration whose header kid is the test log key, published at 3 as a log key: the log has published a declaration key (at 4) and this is not it, so the declaration is under no declaration key the log published (R6.62(b)). It fails, which is not could-not-check and is never disputed: a log key never declares, and a head's signer is no declaration's.",
            log, post, [0, 1, 5], "failed", "declaration-key-unpublished")
        {
            ExtraLogKeys = [new ExtraLogKey(ConformanceLogKeys.Log, LogKeyValidFrom, logKeyIndex)],
            DeclarationKeys = [new ExtraLogKey(ConformanceLogKeys.Declaration, LogKeyValidFrom, declarationKeyIndex)],
        };
    }

    /// <summary>
    /// A key published both as a log key and as a declaration key: 0 enrolled, 1 binding, 2 the post, 3 the key as a log key, 4 the same key as a declaration key,
    /// 5 the declaration it signed. R6.62(d): a declaration key that is also a log key never declares.
    /// </summary>
    private static Case DeclarationKeyIsLogKey(string root, Key k1)
    {
        var log = EnrolledAndBound(k1);
        var post = AddPost(log, k1, "56");
        var logKeyIndex = PublishLogKey(log, ConformanceLogKeys.Log);
        var declarationKeyIndex = PublishDeclarationKey(log, ConformanceLogKeys.Log);
        AddDeclaration(log, new Decl(ConformanceLogKeys.Log, [k1.Kid], FromIndex: 1, Prev: 1), root, "compromise-declaration-key-is-log-key");
        return new Case("compromise-declaration-key-is-log-key", "R6.62",
            "The test log key is published at 3 as a log key and at 4 as a declaration key, and signs the declaration at 5: the key is published, in position and before the declaration, and it is also a log key (R6.62(d)), so it fails.",
            log, post, [0, 1, 5], "failed", "declaration-key-is-log-key")
        {
            ExtraLogKeys = [new ExtraLogKey(ConformanceLogKeys.Log, LogKeyValidFrom, logKeyIndex)],
            DeclarationKeys = [new ExtraLogKey(ConformanceLogKeys.Log, LogKeyValidFrom, declarationKeyIndex)],
        };
    }

    /// <summary>
    /// Two declaration keys published, the key set serving the later one first: 0 enrolled, 1 binding, 2 the post, 3 the first declaration key's publication (the
    /// fixed declaration key), 4 the second's (the fixed unpublished signer, here published), 5 the declaration. <paramref name="underFirst"/> signs it under the first
    /// key (the control: disputed) and otherwise under the second (failed: the first published is the one, whatever order the set is served in, R6.62(e)).
    /// </summary>
    private static Case TwoDeclarationKeys(string root, Key k1, bool underFirst)
    {
        var name = underFirst ? "compromise-first-of-two-declaration-keys" : "compromise-second-declaration-key";
        var log = EnrolledAndBound(k1);
        var post = AddPost(log, k1, underFirst ? "58" : "57");
        var firstIndex = PublishDeclarationKey(log, ConformanceLogKeys.Declaration);
        var secondIndex = PublishDeclarationKey(log, ConformanceLogKeys.Unpublished);
        AddDeclaration(log, new Decl(underFirst ? ConformanceLogKeys.Declaration : ConformanceLogKeys.Unpublished, [k1.Kid], FromIndex: 1, Prev: 1), root, name);
        return new Case(name, "R6.62",
            underFirst
                ? "Two declaration keys are published, at 3 and 4, and the key set serves the second first. The declaration at 5 is signed under the first published, at 3: the first published is the one, by log_index and never by the order the set is served in, so the declaration holds and the post is disputed. The control of compromise-second-declaration-key: the same log, signed under the other key."
                : "Two declaration keys are published, at 3 and 4, and the key set serves the second first. The declaration at 5 is signed under the second, published at 4: it is not the first the log published, whatever order the key set is served in (R6.62(e)), so it fails.",
            log, post, [0, 1, 5], underFirst ? "disputed" : "failed", underFirst ? "disputed" : "declaration-key-not-first")
        {
            DeclarationKeys =
            [
                new ExtraLogKey(ConformanceLogKeys.Unpublished, LogKeyValidFrom, secondIndex),
                new ExtraLogKey(ConformanceLogKeys.Declaration, LogKeyValidFrom, firstIndex),
            ],
        };
    }

    /// <summary>
    /// A key set that serves no <c>declaration_keys</c> member at all, over a log that holds a declaration key and a declaration under it: an absence says nothing (R6.62(a)),
    /// so the declaration is could not be checked, not failed.
    /// </summary>
    private static Case DeclarationKeySetAbsent(string root, Key k1)
    {
        var (log, post, _, decl) = PostThenDeclaration(k1, "59");
        AddDeclaration(log, decl, root, "compromise-declaration-key-set-absent");
        return new Case("compromise-declaration-key-set-absent", "R6.62",
            "The log holds a declaration key at 3 and a declaration under it at 4, and the key set the reader is served carries no declaration_keys member at all: an older Forum, or none said. An absence is not a denial (R6.62(a)), so the declaration is could not be checked.",
            log, post, [0, 1, 4], "could-not-check", "declaration-key-set-not-supplied");
    }

    /// <summary>
    /// A key set that serves <c>"declaration_keys":[]</c>, with a declaration under the fixed declaration key that no entry publishes: 0 enrolled, 1 binding, 2 the
    /// post, 3 the declaration. A served empty array says the log published none, which is a denial (R6.62(b)), the other half of the absent member's pair.
    /// </summary>
    private static Case DeclarationKeysEmpty(string root, Key k1)
    {
        var log = EnrolledAndBound(k1);
        var post = AddPost(log, k1, "60");
        AddDeclaration(log, new Decl(ConformanceLogKeys.Declaration, [k1.Kid], FromIndex: 1, Prev: 1), root, "compromise-declaration-keys-empty");
        return new Case("compromise-declaration-keys-empty", "R6.62",
            "The key set is served with \"declaration_keys\":[], a declaration key that no entry publishes signed the declaration at 3: the log says it published none, so the declaration is under no declaration key (R6.62(b)) and fails. The absent member's pair: an absence is could not be checked, an empty member is a denial.",
            log, post, [0, 1, 3], "failed", "declaration-key-unpublished")
        { DeclarationKeys = [] };
    }

    private static Case FromIndexBeforeBinding(string root, Key k1)
    {
        var (log, post, logKeyIndex, decl) = PostThenDeclaration(k1, "49", d => d with { FromIndex = 0 });
        AddDeclaration(log, decl, root, "compromise-from-index-before-binding");
        return new Case("compromise-from-index-before-binding", "R6.57",
            "from_index is 0 and the first kid's binding is at 1: one below the log index of kids[0]'s binding (KF3).",
            log, post, [0, 1, 4], "failed", "declaration-mismatch")
        { DeclarationKeys = [new ExtraLogKey(ConformanceLogKeys.Declaration, LogKeyValidFrom, logKeyIndex)] };
    }

    // ---- entries -------------------------------------------------------------------------------

    /// <summary>A <c>log.key</c> entry, as the operator's tool publishes a log key (R6.50): <c>{ kid, jwk, valid_from }</c>.</summary>
    private static int PublishLogKey(Log log, P256LogKey key) => log.Add("log.key", "log:keys", OperatorRole, Obj(
        ("jwk", key.Jwk), ("kid", Str(key.Kid)), ("valid_from", Str(LogKeyValidFrom))));

    /// <summary>A <c>log.declaration-key</c> entry, as the operator's publish-declaration-key appends it (errata G67, R6.62): <c>{ kid, jwk, valid_from }</c>.</summary>
    private static int PublishDeclarationKey(Log log, P256LogKey key) => log.Add("log.declaration-key", "log:declaration-keys", OperatorRole, Obj(
        ("jwk", key.Jwk), ("kid", Str(key.Kid)), ("valid_from", Str(LogKeyValidFrom))));

    internal static CanonicalBytes DeclarationStatement(string agent, string[] kids, long fromIndex, long prev, string reason, string typ) =>
        Canon(Obj(
            ("agent_id", Str(agent)),
            ("from_index", Num(fromIndex)),
            ("kids", new JsonValue.Array([.. kids.Select(k => Str(k))])),
            ("prev", Num(prev)),
            ("reason", Str(reason)),
            ("typ", Str(typ))));

    private static int AddDeclaration(Log log, Decl d, string root, string caseName)
    {
        var canonical = DeclarationStatement(Agent, d.Kids, d.FromIndex, d.Prev, d.Reason, d.StatementTyp);
        var text = Encoding.UTF8.GetString(canonical.Span);
        var declaration = PinnedOrSigned(
            Path.Combine(root, caseName), Path.Combine("entries"), canonical, text, d.Signer, d.HeaderTyp);
        return log.Add("agent.key-compromised", Agent, OperatorRole, Obj(
            ("agent_id", Str(Agent)),
            ("declaration", Str(declaration)),
            ("from_index", Num(d.FromIndex)),
            ("kids", new JsonValue.Array([.. d.Kids.Select(k => Str(k))])),
            ("prev", Num(d.Prev)),
            ("reason", Str(d.Reason)),
            ("statement", Str(text))));
    }

    /// <summary>
    /// The declaration already pinned in <paramref name="existingDir"/> for exactly this statement, re-verified under the
    /// signer's key and kept; a fresh signature only when the directory does not exist. A directory that exists and holds no
    /// declaration for the statement is refused: ES256 signing is randomized, so re-signing would move bytes a vector pins.
    /// </summary>
    internal static string PinnedOrSigned(
        string existingDir, string entriesSubdirectory, CanonicalBytes canonical, string statementText, P256LogKey signer, string headerTyp)
    {
        var pinned = FindPinned(existingDir, entriesSubdirectory, statementText);
        if (pinned is not null)
        {
            if (!Signing.Verify(canonical, new JwsSignature(pinned), "ES256", signer.Kid, signer.Spki, headerTyp).IsOk)
                throw new InvalidOperationException($"{existingDir}: the pinned declaration does not verify under its log key and typ; it is kept, never re-signed");
            return pinned;
        }

        if (Directory.Exists(existingDir))
        {
            throw new InvalidOperationException(
                $"{existingDir} exists but pins no declaration for this statement; the generator never re-signs. Delete the case deliberately to regenerate it.");
        }

        return Signing.Sign(canonical, "ES256", signer.Kid, signer.EcPrivateKeyDer, headerTyp).Compact;
    }

    private static string? FindPinned(string dir, string entriesSubdirectory, string statementText)
    {
        var searchDir = Directory.Exists(Path.Combine(dir, entriesSubdirectory)) ? Path.Combine(dir, entriesSubdirectory) : dir;
        if (!Directory.Exists(searchDir))
            return null;

        foreach (var file in Directory.EnumerateFiles(searchDir, "*.json").Order(StringComparer.Ordinal))
        {
            using var document = JsonDocument.Parse(File.ReadAllBytes(file));
            var root = document.RootElement;
            var entry = root.ValueKind == JsonValueKind.Object && root.TryGetProperty("entry", out var inner) ? inner : root;
            if (entry.ValueKind != JsonValueKind.Object
                || !entry.TryGetProperty("event_type", out var type) || type.GetString() != "agent.key-compromised"
                || !entry.TryGetProperty("payload", out var payload) || payload.ValueKind != JsonValueKind.Object
                || !payload.TryGetProperty("statement", out var statement) || statement.GetString() != statementText
                || !payload.TryGetProperty("declaration", out var declaration))
            {
                continue;
            }

            return declaration.GetString();
        }

        return null;
    }

    /// <summary>The key-set members after the head key's, as JSON text starting with a comma per key.</summary>
    private static string ExtraLogKeysJson(IReadOnlyList<ExtraLogKey> keys)
    {
        var builder = new StringBuilder();
        foreach (var extra in keys)
        {
            var members = new List<(string, JsonValue)>
            {
                ("alg", Str("ES256")),
                ("crv", Str("P-256")),
                ("kid", Str(extra.Key.Kid)),
                ("kty", Str("EC")),
                ("use", Str("sig")),
                ("valid_from", Str(extra.ValidFrom)),
                ("x", Str(Jwk.Base64UrlEncode(extra.Key.X32))),
                ("y", Str(Jwk.Base64UrlEncode(extra.Key.Y32))),
            };
            if (extra.LogIndex is { } index)
                members.Add(("log_index", Num(index)));
            builder.Append(',').Append(Encoding.UTF8.GetString(Canon(Obj([.. members])).Span));
        }

        return builder.ToString();
    }

    /// <summary>The key set's <c>declaration_keys</c> member as JSON text, starting with a comma; empty where the case serves no member at all (R6.62(a)).</summary>
    private static string DeclarationKeysJson(Case c) =>
        c.DeclarationKeys is null
            ? string.Empty
            : ",\"declaration_keys\":[" + ExtraLogKeysJson(c.DeclarationKeys).TrimStart(',') + "]";
}
